import{templates}from"./templates.js";export function iniciarSPA(){const e=document.querySelectorAll("nav ul li a"),t=document.querySelector("main");e.forEach(e=>{e.addEventListener("click",n=>{const r=e.getAttribute("href");r.endsWith(".html")&&(n.preventDefault(),async function(e){if(templates[e])t.innerHTML=templates[e];else{const n=await fetch(e),r=await n.text();t.innerHTML=function(e){const t=(new DOMParser).parseFromString(e,"text/html");return t.querySelector("main").innerHTML}(r)}window.scrollTo(0,0)}(r))})})}